package com.viergegroup.swmain.websecurity.bodyencryptor

enum class PrivateRSATx (var id:String,val modulus:String,val exponent:String="010001"){

    RSA01("01","",""),
    RSA02("11","",""),
    RSA03("93","",""),
    RSA04("07","",""),
    RSA05("27","",""),
    RSA06("CA","",""),
    RSA07("0B","",""),
    ;
    companion object{
        fun getRsas():List<PrivateRSATx>{
            return PrivateRSATx.values().toList()
        }

    }

}